import{_ as t,o as r,c as s,ah as a}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Leave requests","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/conges.md","filePath":"src/en/guide/conges.md"}'),o={name:"en/guide/conges.md"};function i(n,e,d,h,l,u){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="leave-requests" tabindex="-1">Leave requests <a class="header-anchor" href="#leave-requests" aria-label="Permalink to &quot;Leave requests&quot;">​</a></h1><p>Leave is one of the few parts of ERA that doesn&#39;t depend on your role: <strong>every staff member</strong> files their own requests, whether they teach, run the cash desk, the infirmary or the boarding house. The decision follows the same rule as the other requests: the direction of the person&#39;s site, the general direction or the administration.</p><h2 id="filing-a-request" tabindex="-1">Filing a request <a class="header-anchor" href="#filing-a-request" aria-label="Permalink to &quot;Filing a request&quot;">​</a></h2><p>From <strong>My leave requests</strong>:</p><ol><li>Pick the <strong>type</strong>: paid leave, unpaid leave or sick leave.</li><li>Set the <strong>start date</strong> and <strong>end date</strong>.</li><li>Write the <strong>reason</strong>.</li><li>Click <strong>Submit request</strong>.</li></ol><p>The request is created as <strong>Pending</strong>. There&#39;s nothing else to do: the direction of your site, the general direction and the administration are told, and see it on their <a href="/era-guide/en/guide/direction/a-approuver.html">To approve</a> page.</p><p>When your request is decided, you get a notification: leave granted, or rejected with the reason.</p><h2 id="following-your-requests" tabindex="-1">Following your requests <a class="header-anchor" href="#following-your-requests" aria-label="Permalink to &quot;Following your requests&quot;">​</a></h2><p>The <strong>History</strong> section of the same page lists your past and current requests with their status:</p><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th></tr></thead><tbody><tr><td>Pending</td><td>Filed, not reviewed yet</td></tr><tr><td>Approved</td><td>Granted by the administration</td></tr><tr><td>Rejected</td><td>Refused — the rejection reason is shown with the request</td></tr></tbody></table><p>You only ever see your own requests, never a colleague&#39;s.</p><div class="tip custom-block"><p class="custom-block-title">Filing isn&#39;t open to everyone</p><p>This page assumes you have a staff record at the school. An account without one (a parent, a student) has no access to it — see <a href="/era-guide/en/guide/admin/personnel-utilisateurs.html">Staff and user accounts</a> for how records are created.</p></div><h2 id="deciding-on-requests-direction-and-administration" tabindex="-1">Deciding on requests (direction and administration) <a class="header-anchor" href="#deciding-on-requests-direction-and-administration" aria-label="Permalink to &quot;Deciding on requests (direction and administration)&quot;">​</a></h2><p>The direction and the administration get an extra view, <strong>Staff → Leave requests</strong>. A site director sees the requests of their sites&#39; staff; the general director and the administrator, those of <strong>all</strong> staff. Pending requests can also be decided from the <a href="/era-guide/en/guide/direction/a-approuver.html">To approve</a> page, and show in the dashboard&#39;s tasks. Nobody decides their own request.</p><p>For each request:</p><ul><li><strong>Approve</strong> grants it immediately.</li><li><strong>Reject</strong> opens a confirmation dialog asking for a <strong>rejection reason</strong>. That reason is sent to the person concerned with the decision, and stays visible in their own history — which is what saves them from having to come and ask why.</li></ul><p>An already-decided request stays in the list with its outcome: the history is a record, nothing is erased.</p>',17)])])}const p=t(o,[["render",i]]);export{g as __pageData,p as default};
